internal object DuaAmDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("ከመጥፎ ጎረቤት መሸሸጊያ", "አላህ ሆይ፣ በጉዞ ላይ ያለ ጎረቤት ስለሚሄድ ቋሚ መኖሪያ ቦታ ካለው መጥፎ ጎረቤት በአንተ እጠበቃለሁ።", "ከመጥፎ ጎረቤት ለመጠበቅ.", "ነቢዩ ﷺ ከዚህ መጠጊያ እንዲፈልጉ አዝዘዋል።"),
        "dua_ishfi_abdak" to DuaText("ለታመመ ሰው ማገገም", "አሏህ ሆይ ባርያህን ለአንተ ጠላት እንዲጋፈጥ ወይም ላንተ ወደ ሶላት እንዲሄድ ፈውሰው።", "ለታመመው ሰው ሲጎበኙ.", "ነቢዩ ﷺ ለታመሙ እንዲህ ሲል አስተምሯል."),
        "dua_la_mania" to DuaText("የሰጡትን ማንም አይከለክልም።", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው። አሏህ ሆይ የሰጠኸውን የሚከለክለው የለም አንተ የከለከልከውንም የሚሰጥ የለም የባለፀጎችም ሀብት ባንተ ላይ ምንም አይጠቅምም።", "የግዴታ ሶላት ከሰላም በኋላ።", "ነቢዩ ﷺ ከእያንዳንዱ የግዴታ ጸሎት በኋላ እንዲህ ብለዋል ።"),
        "dua_slaughtering" to DuaText("እንስሳ ሲታረድ", "በአላህ ስም አላህም ታላቅ ነው።", "እንስሳ ሲሰዋ ወይም ሲታረድ።", "ነብዩ ﷺ ቢስሚላህ እና ተክቢር በመስዋዕት ጊዜ ተናግረዋል ።"),
        "dua_undressing" to DuaText("ልብሶችን ሲያወልቁ", "በአላህ ስም።", "ልብሶችን ሲያወልቁ (ለጉልበት ወይም ለመለወጥ).", "በጂንና በሰው ብልቶች መካከል መጋረጃ ይሆናል።"),
        "dua_ilbas_jadidan" to DuaText("አዲስ ልብስ የለበሰ ሰው ማየት", "አዲስ ልበሱ፣ የተመሰገነ ኑሩ እና በሰማዕትነት ይሙት።", "አዲስ ልብስ ለብሶ ሙስሊም ወንድሙን ሲያይ።", "ነብዩ ﷺ ይህንን ዱዓ ያደረጉት ኡመር (RA) አዲስ ልብስ ለብሰው ሲያዩ ነበር።"),
        "dua_hajj_la_riya" to DuaText("ከመታየት የጸዳ ሀጅ", "አላህ ሆይ (አድርገው) ሀጅ የማይታይበትና ዝና የማይፈልግ።", "ለሐጅ ዓላማ ሲያደርጉ ለቅንነት።", "ነቢዩ ﷺ ይህን ዱዓ ያደረጉት በሐጅ ጊዜ ነው።"),
        "dua_q_muslimayni_laka" to DuaText("የኢብራሂም እና የኢስማኢል ዱዓ (AS) - ታዛዥ ያድርገን", "ጌታችን ሆይ ለአንተ ታዛዦች አድርገን ከዘሮቻችንም ላንተ ታዛዦች ሕዝቦች አድርገን። የአምልኮ ስርአታችንን አሳየን እና ንስሀችንን ተቀበል። አንተ ጸጸትን ተቀባይ አዛኙ ነህና።", "ለራስ እና ለትውልድ የመገዛት ዱዓ።", "ካዕባን ሲገነቡ የተደረገው ዱዓ።"),
        "dua_q_iftah_baynana" to DuaText("የሹዓይብ ዱዓ (AS) - በመካከላችን ይፍረዱ", "ጌታችን ሆይ በኛና በሕዝቦቻችን መካከል በእውነት ፍረድ አንተም ከፈራጆች ሁሉ በላጭ ነህ።", "በእውነት እና በውሸት መካከል ለፍርድ።", "የሹዓይብ ዱዓ (AS) ህዝቦቹ ሲክዱ።"),
        "dua_q_la_akuna_zahiran" to DuaText("የሙሳ ዱአ (AS) - የወንጀለኞች ረዳት በጭራሽ", "ጌታዬ ሆይ በሰጠኸኝ ችሮታ እኔ የወንጀለኞችን ረዳት አልሆንም።", "ለአላህ ችሮታ ማመስገን እና በዳዮችን ላለመርዳት ቃል መግባት።", "የሙሴ ቃል ኪዳን (AS) ከንስሐ በኋላ።"),
        "dua_q_nuh_unsurni" to DuaText("የኑህ ዱዓ (AS) - እርዱኝ፣ ይክዱኛል።", "ጌታዬ ሆይ እርዳኝ እነሱ ክደዋልና።", "ሰዎች ሲክዱህ እውነትን ሲክዱ።", "ምላሽ የሰጠው የኑህ (AS) ዱአ።"),
        "dua_q_ihkum_bil_haqq" to DuaText("ጌታዬ በእውነት ፍረድ", "My Lord, judge with truth. ጌታችንም በጣም ርኅሩኅ ነው፣ በምትገልጹት ነገር ላይ እርዳታው የሚፈለግ ነው።", "በውሸት እና በሐሰት ክሶች ፊት.", "ﷺ ለነቢዩ ያስተማረው ዱአ።"),
        "dua_ghalabatid_dayn" to DuaText("ዕዳ እና ጠላቶችን ከመጨፍለቅ መሸሽ", "አላህ ሆይ በዕዳ ከመሸነፍ፣ በጠላት ከመሸነፍና በጠላቶች ከመኩራራት በአንተ እጠበቃለሁ።", "ከዕዳ ሸክም ጥበቃ እና ከጠላቶች የበላይነት.", "ነቢዩ ﷺ ከእነዚህ ነገሮች መጠጊያ ይሹ ነበር።"),
        "dua_faqr_qillah_dhillah" to DuaText("ከድህነት እና ከውርደት መሸሸጊያ", "አላህ ሆይ ከድህነት፣ ከድህነት እና ከውርደት እንዲሁም ሌሎችን ከመበደል ወይም ከመበደል በአንተ እጠበቃለሁ።", "ከችግር፣ ከፍላጎትና ከውርደት ለመዳን።", "ﷺ በነቢዩ ያስተማረው መሸሸጊያ።"),
        "dua_five_things_new_muslim" to DuaText("ይቅርታ አድርግ ፣ ምህረት አድርግ ፣ ምራ ፣ ፈውስ ፣ አቅርብ", "አሏህ ሆይ ይቅር በለኝ ፣ ማረኝ ፣ ምራኝ ፣ ደህንነትን ስጠኝ ፣ ስጠኝ ።", "ነቢዩ ﷺ ይህንን ዱዓ ከፀሎት ጋር ለአዳዲስ ሙስሊሞች አስተማሩ።", "ነቢዩ ﷺ እንዲህ ብለዋል፡- እነዚህ ቃላት ዓለምንና ወዲያውን ለእናንተ ይሰበስባሉ።"),
        "dua_ruku_laka_raka_tu" to DuaText("በሩኩ - ላንቺ ሰገድኩ።", "አሏህ ሆይ ላንተ ሰገድኩ ባንተ አምኜ ለአንተ ተገዛሁ። መስሚያዬ፣ እይታዬ፣ አእምሮዬ፣ አጥንቶቼና ጅማቶቼ በፊትህ ተዋረዱ።", "በሩኩ (በተለይ በበጎ ፈቃደኝነት)።", "ነብዩ ﷺ በሩኩ ላይ አነበቡት።"),
        "dua_sujood_laka_sajadtu" to DuaText("በሱጁድ - ላንተ ሰገድኩ።", "አላህ ሆይ ላንተ ሰገድኩ ባንተ አምኜ ለአንተ ተገዛሁ። ፊቴ ለፈጠረው፣ ለፈጠረውም፣ ለፈጠረውም፣ መስሚያውንና ማያውንም ላወጣው ጌታ ሰግዷል። ከፈጣሪዎች ሁሉ በላጭ የሆነው አላህ ተባረከ።", "በሱጁድ (በተለይ በውዴታ ሶላት)።", "ነብዩ ﷺ ይህንን በሱጁድ አንብበውታል።"),
        "dua_ruku_sujood_subhanaka" to DuaText("ክብር ላንተ ይሁን ጌታችን - ይቅር በለኝ", "ክብር ላንተ ይሁን ጌታችን አላህ ሆይ ምስጋናም ላንተ ይሁን። አላህ ሆይ ይቅር በለኝ።", "በሩኩና በሱጁድ።", "አኢሻ (RA)፡ ነቢዩ ﷺ ብዙ ጊዜ በሩኩና በሱጁድ ተናግረው ነበር።"),
        "dua_q_musa_li_akhi" to DuaText("የሙሳ ዱዓ (AS) - እኔን እና ወንድሜን ይቅር በሉ።", "ጌታዬ ሆይ እኔንና ወንድሜን ይቅር በለን በእዝነትህም ውስጥ አግባን አንተ ከአዛኞች ሁሉ በላይ አዛኝ ነህና።", "ለራስ እና ለወንድም ወይም ለሚወዷቸው ሰዎች ይቅርታ.", "የሙሳ ዱዓ (AS) ለሀሩን (AS)።"),
        "dua_q_ufawwidu_amri" to DuaText("ጉዳዬን ለአላህ አደራ እላለሁ።", "ጉዳዬንም ለአላህ አደራ እላለሁ። አላህ በባሮቹ ላይ ተመልካች ነው።", "ሰዎች ሲቃወሙህ እና ጉዳዩ ለአላህ ብቻ መሆን አለበት።", "የሙእሚኑ ቃል ከፈርዖን ሰዎች; ከዚያም አላህ ከመጥፎ ተንኮላቸው ጠበቀው።"),
        "dua_q_hawariyyun" to DuaText("የደቀመዛሙርት ዱዓ - ከምሥክሮቹ ጋር ይመዝግቡን።", "ጌታችን ሆይ አንተ ባወረድከው አመንን። መልክተኛውንም ተከተልን፤ ከመስካሪዎችም መዝገብን።", "በእምነት እና መልእክተኛውን በመከተል ላይ ለመፅናት።", "የኢሳ ደቀመዛሙርት ዱዓ (AS)።"),
        "dua_q_la_tukhzini" to DuaText("የኢብራሂም ዱዓ (AS) - አታሳፍሩኝ", "በሚቀሰቀሱበትም ቀን አታሳፍረኝ።", "በትንሣኤ ቀን ከውርደት ለመዳን።", "የኢብራሂም ዱአ (AS) ለቀጣይ።"),
        "dua_iftar_laka_sumtu" to DuaText("ኢፍጣር - ለአንተ ጾምኩ", "አሏህ ሆይ ላንተ ፆሜአለሁ በአንተም ሲሳይ ፆምያለው።", "ፆም ሲፈታ (የታወቀው የኢፍጣር ዱአ)።", "ነቢዩ ﷺ ኢፍጣር ላይ እንዲህ አሉ። በሌሎች ዘገባዎች የተጠናከረ ሙርሳል ዘገባ ነው; ኢፍጣር ላይ ማንበብ የሀነፊዮች እና የብዙሃኑ ተግባር ነው።"),
        "dua_iftar_ibn_umar" to DuaText("ኢፍጣር - በታላቅ ምሕረትህ ፣ ይቅር በለኝ", "አላህ ሆይ ይቅር እንድትለኝ ሁሉንም ነገር ባካበተች ምህረትህ እለምንሃለሁ።", "በኢፍጣር - አብዱላህ ኢብኑ አምር (RA) ይህንን ዱአ አደረገ; የኢፍጣር ፆመኛ ዱዓ አይከለከልም።", "ሀዲስ፡- ፆመኛ በኢፍጣር ጊዜ የሚያቀርበው ዱዓ ውድቅ አይደረግም።"),
        "dua_inni_saim" to DuaText("በጾም ጊዜ ሲናደድ", "እጾማለሁ፣ እጾማለሁ።", "አንድ ሰው ሲሰድብህ ወይም ሲጣላህ።", "ነቢዩ ﷺ እንዲህ ብለዋል፡- ጾም ጋሻ ነው፣ ስለዚህ ጾመኛው ጸያፍ አይናገር ወይም ባለማወቅ አይሠራ - አንድ ሰው ከተጣላ ይህን ሁለት ጊዜ ተናገር።"),
        "dua_eid_takbeer" to DuaText("ወደ ኢድ በሚወስደው መንገድ ላይ ተክቢራ", "አሏህ ታላቅ ነው አሏህ ታላቅ ነው ከአላህ በስተቀር ሌላ አምላክ የለም አላህም ታላቅ ነው አላህ ታላቅ ነው ምስጋናም ሁሉ ለአላህ ይሁን።", "ከጨረቃ ሌሊት ጀምሮ እስከ ኢድ አልፈጥር ሰላት ድረስ በተለይም ወደ ኢድ መሬት በሚወስደው መንገድ ላይ።", "የቁርኣን ትእዛዝ፡- ‘ቁጥሩን እንድትሞሉና የአላህን ታላቅነት እንድታውጁ’ (አል-በቀራህ 2፡185)። ኢብኑ መስዑድ (RA) ይህን ተክቢር ተናግሯል።"),
        "dua_ahsin_aqibatana" to DuaText("በሁሉም ጉዳዮች መጨረሻችንን መልካም ያድርግልን", "አላህ ሆይ ፍፃሜያችንን በነገር ሁሉ መልካም አድርገን በዱንያም ከውርደት በአኺራም ከቅጣት ጠብቀን።", "በእያንዳንዱ ጉዳይ ላይ ጥሩ ውጤት ለማግኘት.", "ይህን ዱዓ ያደረገ እና ለፍርድ ከመቅረቡ በፊት የሞተ ሁሉ ይሞታል (ከችሎት የተጠበቀ)።"),
        "dua_fadlika_wa_rahmatik" to DuaText("ምህረትህን እና ችሮታህን እጠይቃለሁ።", "አሏህ ሆይ ከችሮታህ እና ከችሮታህ እለምንሃለሁ ካንተ በቀር ማንም አይይዘውምና።", "ሲሳይንና ምህረትን ሲጠይቁ።", "እንግዶች ወደ ነቢዩ ﷺ ምግብ በማይኖርበት ጊዜ; ይህን ዱዓ አደረገ፣ ከዚያም ስጦታ መጣ።"),
        "dua_allahu_akbar_kabira_2696" to DuaText("ለባዳዊን የተማሩ ቃላት", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። አላህም ታላቁ ታላቅ ነው። ምስጋና ለአላህ ይገባው። የዓለማት ጌታ ለኾነው አላህ ይገባው። ምንም ኃይልም ኃይልም የለም። አሸናፊው ጥበበኛው አላህ ዘንድ ቢሆን እንጂ።", "አጠቃላይ የዚክር እና የዱዓ ሀረግ - ለበዳዊን አስተማረ።", "ከዚህ በኋላ 'አላሙመግፊር ሊ ዋርሃምኒ ወህዲኒ ወርዙቅኒ' እንዲል ተምሯል።"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("በፊት እና በኋላ የላክሁትን ይቅር በል።", "አላህ ሆይ በፊትና በኋላ የሰራሁትን ሀጢያት ፣በድብቅ የሰራሁትን እና በግልፅ የሰራሁትን ፣የሰራሁትን ፣ያሳለፍኩትን እና ከእኔ የበለጠ የምታውቀውን ይቅር በለኝ። አንተ ወደፊት የምታመጣ አንተም የምትመልስ ነህ; ከአንተ በቀር ሌላ አምላክ የለም።", "ከተሻሁድ እና ሰለዋት በኋላ፡ ከሰላም በፊት።", "ነብዩ ﷺ ይህንን በሶላት መጨረሻ ላይ ፣ በታሸሁድ እና በሰላም መካከል አነበቡት ።"),
        "dua_jiddi_wa_hazli" to DuaText("የኔን ቁምነገርና ቀልቤን ይቅር በል።", "አላህ ሆይ የሰራሁትን ኃጢአት በስህተት እና ሆን ብዬ በቁም ነገር እና በመቀለድ ይቅር በለኝ - ያ ሁሉ በውስጤ ነው።", "ለታወቀ እና ለማይታወቅ ለማንኛውም አይነት ኃጢአት ይቅርታ።", "አጠቃላይ የነቢዩ ኢስቲግፋር ﷺ።"),
        "dua_rising_ruku_mil" to DuaText("ከሩኩ በኋላ - ሰማያትን የሚሞሉ ምስጋናዎች", "ጌታችን ሆይ! ሰማያትን የሞላህ፣ ምድርንም የሞላህ፣ ከዚያ በኋላ የምትሻውን ሁሉ የምትሞላ፣ ምስጋና ላንተ ብቻ ነው።", "ከሩኩ ከተነሳ በኋላ፣ ከ‘ራባና ላካል-ሃምድ’ ጋር።", "ነቢዩ ﷺ ከሩኩ ሲነሱ እንዲህ አሉ።"),
        "dua_istiftah_kabira" to DuaText("አላህ ታላቅ ምስጉን ነው።", "አላህም ታላቁ ታላቅ ነው። ምስጋና ለአላህ ይገባው። ጧትም ማታም ለአላህ ይገባው።", "ጸሎቱን ሲጀምር (የመክፈቻው ውዳሴ አንድ ዓይነት)።", "ነቢዩ ﷺ እንዲህ ብለዋል፡- የሰማይ በሮች ተከፈቱለት።"),
        "dua_q_ashku_bathhi" to DuaText("የያዕቆብ ዱዓ (AS) - አቤት የምለው ለአላህ ብቻ ነው።", "ጭንቀቴን እና ሀዘኔን የምማረረው ለአላህ ብቻ ነው።", "በጥልቅ ሀዘን እና መለያየት።", "ያዕቆብ (AS) ከዩሱፍ (AS) በመለየቱ ይህን ተናግሯል።"),
        "dua_q_khayrun_hafiza" to DuaText("አላህ በላጭ ጠባቂ ነው።", "አላህ በላጭ ጠባቂ ነው እርሱም ከአዛኞች በጣም አዛኝ ነው።", "ልጆችን ወይም የሚወዷቸውን ሰዎች በጉዞ ላይ ሲልኩ.", "ያዕቆብ (AS) ልጁን ለአላህ አደራ ሲሰጥ እንዲህ አለ።"),
        "dua_q_aqraba_rashada" to DuaText("ጌታዬ ቀኙን ይምራኝ።", "ጌታዬ ከዚህ በጣም ቅርብ ወደ ሆነች ሥራ ሊመራኝ ይከጀላል።", "በአንዳንድ ጉዳዮች የተሻለ መንገድ ሲፈልጉ.", "ነቢዩ ﷺ ሲረሱ ይህን እንዲናገሩ ተነግሯቸዋል።"),
        "dua_q_sawa_as_sabil" to DuaText("የሙሳ ዱዓ (AS) - ወደ ትክክለኛው መንገድ ምራኝ።", "ምን አልባት ጌታዬ ቅኑን መንገድ ይመራኛል።", "አዲስ ጉዞ ወይም ያልተለመደ መንገድ ላይ ሲወጡ።", "ሙሳ (AS) ወደ ማድያን ሲዞር እንዲህ አለ።"),
        "dua_q_not_among_wrongdoers" to DuaText("ከበደለኞች መካከል አታድርገኝ", "ጌታዬ ሆይ ከበደለኞች ሕዝቦች አታድርገኝ።", "አላህን ከበደለኞች እንዲርቅ የሚለምን ዱዓ።", "አላህን ከበደለኞች እንዲርቅ የሚለምን ዱዓ።"),
        "dua_q_do_not_make_us_trial" to DuaText("ፈተና አታድርገን", "ጌታችን ሆይ በከሓዲዎች ላይ ፈተና አታድርገን ጌታችን ሆይ ማረን። አንተ አሸናፊው ጥበበኛው ነህና።", "የኢብራሂም (AS) እና የባልደረቦቻቸው ዱአ።", "የኢብራሂም (AS) እና የባልደረቦቻቸው ዱአ።"),
        "dua_morning_witness" to DuaText("የጠዋት ምስክር ለተውሂድ", "አላህ ሆይ፣ ጠዋቱን ገብቻለሁ። አንተን፣ የዙፋንህን ተሸካሚዎች፣ መላእክቶችህን እና ፍጥረታትህን ሁሉ ምስክር አደርጋለሁ፤ አንተ አላህ ነህ፣ ከአንተ በስተቀር አምላክ የለም፣ አንተ ብቻህን ነህ፣ አጋር የለህም፣ ሙሐመድ ﷺ ባሪያህና መልእክተኛህ ነው።", "ትረካው ጠዋት አራት ጊዜ መናገሩን ይጠቅሳል።", "ትረካው ጠዋት አራት ጊዜ መናገሩን ይጠቅሳል።"),
    )
}
